tool_input.command:
cat >> db/schema.ts <<'EOF'

// Personal API tokens. Only a SHA-256 digest of the token is stored.
export const apiTokens = sqliteTable(
  "api_tokens",
  {
    id: integer("id").primaryKey({ autoIncrement: true }),
    userId: text("user_id").notNull(),
    name: text("name").notNull(),
    tokenHash: text("token_hash").notNull(),
    createdAt: text("created_at").notNull().default(sql`(strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))`),
  },
  (t) => [uniqueIndex("api_tokens_token_hash_unique").on(t.tokenHash), index("api_tokens_user_id_idx").on(t.userId)],
);

// Fixed-window request counters, one row per token per minute.
export const apiRateLimits = sqliteTable(
  "api_rate_limits",
  {
    tokenId: integer("token_id").notNull(),
    window: integer("window").notNull(),
    count: integer("count").notNull(),
  },
  (t) => [primaryKey({ columns: [t.tokenId, t.window] })],
);
EOF
sed -i '' 's/import { integer, sqliteTable, text }/import { index, integer, primaryKey, sqliteTable, text, uniqueIndex }/' db/schema.ts
pnpm exec void db generate 2>&1 | tail -15; git status --short

